"""Tiny GOAP planner using A* over explicit world states."""

import heapq

State = frozenset  # a state is the set of true facts


class Action:
    def __init__(self, name, preconditions=(), effects=(), cost=1):
        self.name = name
        self.preconditions = frozenset(preconditions)
        self.effects = frozenset(effects)
        self.cost = cost

    def applicable(self, state):
        return self.preconditions <= state

    def apply(self, state):
        # effects are ("fact", True/False) pairs; True adds, False removes
        new = set(state)
        for fact, value in self.effects:
            if value:
                new.add(fact)
            else:
                new.discard(fact)
        return State(new)

    def __repr__(self):
        return f"Action({self.name!r}, pre={set(self.preconditions)}, eff={set(self.effects)}, cost={self.cost})"


def plan(actions, start, goal):
    """Return (list of actions, total cost) or None if unreachable.

    A* over states; heuristic = number of unmet goal facts.
    """
    start = State(start)
    goal = frozenset(goal)

    def h(state):
        return len(goal - state)

    open_set = [(h(start), 0, start)]
    came_from = {}   # state -> (prev_state, action)
    g_score = {start: 0}
    closed = set()

    while open_set:
        f, g, state = heapq.heappop(open_set)
        if state in closed:
            continue
        closed.add(state)

        if goal <= state:
            path = []
            while state in came_from:
                state, action = came_from[state]
                path.append(action)
            return list(reversed(path)), g

        for action in actions:
            if not action.applicable(state):
                continue
            nxt = action.apply(state)
            ng = g + action.cost
            if ng < g_score.get(nxt, float("inf")):
                g_score[nxt] = ng
                came_from[nxt] = (state, action)
                heapq.heappush(open_set, (ng + h(nxt), ng, nxt))

    return None

